shell_commands:
/bin/zsh -lc "cat > src/orchestration/tools/registry.nested-path.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

describe('ToolRegistry nested validation', () => {
  it('reports the nested path for a wrong type specs/hal-engine-tool-input-validation/spec.md#2', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {name: 'nested', description: 'Nested', inputSchema: {type: 'object', properties: {address: {type: 'object', properties: {city: {type: 'string'}}}}}},
      async () => 'ok',
    );
    const response = await registry.execute('nested', {address: {city: 123}});
    expect(response.result).toMatch(/\\/address\\/city.*string/);
  });
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/registry.nested-path.test.ts"
